/**
 * The exact filter probes run at planning time while the query holds its dataset lease, so every one of them must stop
 * at its caller-supplied bound and must report a capped walk as inconclusive (never cached, never served as a proof)
 * rather than as an exact answer.
 */
class LmdbFilterProbeScanCapTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final SketchSnapshotIdentity SNAPSHOT = new SketchSnapshotIdentity(11L, 29L, 7L);
	private static final long PREDICATE_ID = 2L;
	private static final long DROP_ID = 3L;
	private static final long KEEP_ID = 4L;

	@Test
	void exactZeroProbeStopsAtTheRowCapAndNeverCachesTheCappedWalk(@TempDir Path dataDir) throws Exception {
		// Twenty rows, every one of them rejected by FILTER(?value = "keep"): the zero is real but a cap of eight
		// rows cannot prove it.
		long[][] rows = new long[20][];
		for (int ordinal = 0; ordinal < rows.length; ordinal++) {
			rows[ordinal] = row(100L + ordinal, PREDICATE_ID, DROP_ID);
		}
		ProbeFixture fixture = fixture(dataDir, rows);
		Filter filter = filter("subject", "value", "keep");

		assertFalse(fixture.stats.isExactBoundedFilterZero(filter, pattern(filter), 8),
				"a walk that hits the row cap is inconclusive even when every scanned row was rejected");
		int firstScan = fixture.delivered.get();
		assertTrue(firstScan <= 9 && firstScan >= 8,
				"the scan must stop right after the cap is exceeded, delivered=" + firstScan);

		assertFalse(fixture.stats.isExactBoundedFilterZero(filter, pattern(filter), 8),
				"an inconclusive walk is not cached, so a second call is still inconclusive");
		assertTrue(fixture.delivered.get() >= 2 * 8, "the second call must walk again instead of serving a cached "
				+ "capped result, delivered=" + fixture.delivered.get());
		verify(fixture.tripleStore, times(2)).getTriples(any(Txn.class), anyLong(), anyLong(), anyLong(), anyLong(),
				anyBoolean());

		assertTrue(fixture.stats.isExactBoundedFilterZero(filter, pattern(filter), 4_096),
				"a bound above the row count completes the walk and proves the zero");
	}

	@Test
	void exactZeroProbeCapIsPerCallAndACompleteProofIsOnlyCachedForItsOwnBound(@TempDir Path dataDir)
			throws Exception {
		long[][] rows = { row(1L, PREDICATE_ID, DROP_ID), row(5L, PREDICATE_ID, DROP_ID) };
		ProbeFixture fixture = fixture(dataDir, rows);
		Filter filter = filter("subject", "value", "keep");

		assertTrue(fixture.stats.isExactBoundedFilterZero(filter, pattern(filter), 4_096));
		// The cache key includes the bound, so a tighter bound is answered by its own (inconclusive) walk.
		assertFalse(fixture.stats.isExactBoundedFilterZero(filter, pattern(filter), 1),
				"a proof completed under a larger bound must not be served for a bound the walk would exceed");
	}

	@Test
	void distinctSupportProbeReportsTheSupportLimitInsteadOfAnEnumeration(@TempDir Path dataDir)
			throws Exception {
		long[][] rows = new long[6][];
		for (int ordinal = 0; ordinal < rows.length; ordinal++) {
			rows[ordinal] = row(100L + ordinal, PREDICATE_ID, 200L + ordinal);
		}
		ProbeFixture fixture = fixture(dataDir, rows);
		Filter filter = filter("subject", "value", "keep");

		DistinctFilterValues limited = fixture.stats.exactMatchingDistinctValues(pattern(filter),
				filter.getCondition(), "value", 3);
		assertEquals(DistinctFilterStatus.SUPPORT_LIMIT, limited.status(),
				"six distinct terms exceed a support cap of three");
		assertTrue(limited.matchingValues().isEmpty(), "a capped enumeration publishes no terms. " + limited);
		assertTrue(fixture.delivered.get() <= 4,
				"the walk stops at the (cap + 1)-th distinct term, delivered=" + fixture.delivered.get());

		DistinctFilterValues cached = fixture.stats.exactMatchingDistinctValues(pattern(filter),
				filter.getCondition(), "value", 3);
		assertEquals(DistinctFilterStatus.SUPPORT_LIMIT, cached.status(),
				"the cached answer for a capped enumeration keeps its non-exact status");

		DistinctFilterValues complete = fixture.stats.exactMatchingDistinctValues(pattern(filter),
				filter.getCondition(), "value", 4_096);
		assertEquals(DistinctFilterStatus.COMPLETE, complete.status(),
				"a cap above the distinct count enumerates completely");
		assertEquals(List.of(VF.createLiteral("keep")), complete.matchingValues());
	}

	private static ProbeFixture fixture(Path dataDir, long[]... explicitRows) throws Exception {
		ValueStore valueStore = mock(ValueStore.class);
		TripleStore tripleStore = mock(TripleStore.class);
		TxnManager txnManager = mock(TxnManager.class);
		Txn txn = mock(Txn.class);
		AtomicInteger delivered = new AtomicInteger();
		when(tripleStore.getTxnManager()).thenReturn(txnManager);
		when(txnManager.createReadTxn()).thenReturn(txn);
		when(tripleStore.planningReadTxn()).thenReturn(txn);
		when(valueStore.getId(any(Value.class))).thenReturn(PREDICATE_ID);
		when(valueStore.getValue(anyLong())).thenAnswer(invocation -> {
			long id = invocation.getArgument(0, Long.class);
			if (id == PREDICATE_ID) {
				return new LmdbIRI(null, "urn:test:predicate", id);
			}
			if (id == DROP_ID) {
				return new LmdbLiteral(null, "drop", id);
			}
			if (id == KEEP_ID) {
				return new LmdbLiteral(null, "keep", id);
			}
			if (id >= 200L) {
				// One of the distinct object terms matches the filter, the rest do not.
				return new LmdbLiteral(null, id == 205L ? "keep" : "term-" + id, id);
			}
			return new LmdbIRI(null, "urn:test:subject:" + id, id);
		});
		when(tripleStore.getTriples(any(Txn.class), anyLong(), anyLong(), anyLong(), anyLong(), anyBoolean()))
				.thenAnswer(invocation -> invocation.getArgument(5, Boolean.class)
						? rows(delivered, explicitRows)
						: rows(delivered));
		when(tripleStore.distinctCursorSkipPlan(any(StatementPattern.class)))
				.thenReturn(Optional.of(new LmdbDistinctCursorSkipSupport.Plan("posc", 2, 0, 0)));
		when(tripleStore.getTriplesWithDistinctCursorSkip(any(Txn.class), any(StatementPattern.class), anyLong(),
				anyLong(), anyLong(), anyLong(), anyBoolean(), any(LmdbValueIdFilter.class)))
						.thenAnswer(invocation -> Optional.of(invocation.getArgument(6, Boolean.class)
								? rows(delivered, explicitRows)
								: rows(delivered)));
		LmdbFilterSelectivityStats stats = new LmdbFilterSelectivityStats(
				dataDir.resolve("join-estimator.rjes"), tripleStore, valueStore, false, 0L, 0, false,
				() -> SNAPSHOT, 0, () -> false);
		return new ProbeFixture(stats, tripleStore, delivered);
	}

	private static long[] row(long subject, long predicate, long object) {
		return new long[] { subject, predicate, object, 0L };
	}

	/** An in-memory cursor that counts every row it hands out, so tests can prove where a walk stopped. */
	private static RecordIterator rows(AtomicInteger delivered, long[]... rows) {
		AtomicInteger index = new AtomicInteger();
		return new RecordIterator() {
			@Override
			public long[] next() {
				int next = index.getAndIncrement();
				if (next < rows.length) {
					delivered.incrementAndGet();
					return rows[next];
				}
				return null;
			}

			@Override
			public void close() {
				// Nothing to release in the in-memory test cursor.
			}
		};
	}

	private static Filter filter(String subjectName, String objectName, String expected) {
		String query = "SELECT * WHERE { ?" + subjectName + " <urn:test:predicate> ?" + objectName
				+ " . FILTER(?" + objectName + " = \"" + expected + "\") }";
		Filter[] found = new Filter[1];
		QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null)
				.getTupleExpr()
				.visit(new AbstractQueryModelVisitor<RuntimeException>() {
					@Override
					public void meet(Filter node) {
						if (found[0] == null) {
							found[0] = node;
						}
						super.meet(node);
					}
				});
		return found[0];
	}

	private static StatementPattern pattern(Filter filter) {
		return (StatementPattern) filter.getArg();
	}

	private record ProbeFixture(LmdbFilterSelectivityStats stats, TripleStore tripleStore, AtomicInteger delivered) {
	}
}
